def render(records, columns):
    lines = [" | ".join(columns)]
    for r in records:
        lines.append(" | ".join(str(r.get(c, "")) for c in columns))
    return "\n".join(lines)

def render_with_total(records, columns, total_field):
    body = render(records, columns)
    total = sum(int(r[total_field]) for r in records)
    return body + "\nالإجمالي: " + str(total)

